// Animation phase
void animation_phase(void) {
    if (get_current_wpm() <= IDLE_SPEED) {
        current_idle_frame = (current_idle_frame + 1) % IDLE_FRAMES;
        oled_write_raw_P(idle[abs((IDLE_FRAMES - 1) - current_idle_frame)], ANIMATION_SIZE);
    }
    if (get_current_wpm() > IDLE_SPEED && get_current_wpm() < TAP_SPEED) {
        oled_write_raw_P(prep[0], ANIMATION_SIZE); // remove if IDLE_FRAMES >1
    }
    if (get_current_wpm() >= TAP_SPEED) {
        current_tap_frame = (current_tap_frame + 1) % TAP_FRAMES;
        oled_write_raw_P(tap[abs((TAP_FRAMES - 1) - current_tap_frame)], ANIMATION_SIZE);
    }

    oled_set_cursor(0, 0);                           // sets cursor to (row, column) using character spacing (5 rows on 128x32 screen, anything more will overflow back to the top)
    sprintf(wpm_str, "WPM:%03d", get_current_wpm()); // edit the string to change what shows up, edit %03d to change how many digits show up
    oled_write(wpm_str, false);                      // writes wpm on top left corner of string
}

oled_rotation_t oled_init_user(oled_rotation_t rotation) {
    if (is_keyboard_master()) {
        return OLED_ROTATION_180; // flips the display 180 degrees
    }

    return rotation;
}

bool oled_task_user(void) {
    if (is_keyboard_master()) {
        if (get_current_wpm() != 000) {
            if (timer_elapsed32(animation_timer) > ANIMATION_FRAME_DURATION) {
                animation_timer = timer_read32();
                animation_phase();
            }
            animation_sleep = timer_read32();
        } else {
            if (timer_elapsed32(animation_sleep) > OLED_TIMEOUT) {
                oled_off();
            } else {
                if (timer_elapsed32(animation_timer) > ANIMATION_FRAME_DURATION) {
                    animation_timer = timer_read32();
                    animation_phase();
                }
            }
        }
    } else {
        switch (get_highest_layer(layer_state | default_layer_state)) {
            case 0:
                oled_write_ln("Layer: Colemak-DH", false);
                break;
            case 1:
                oled_write_ln("Layer: QWERTY", false);
                break;
            case 2:
                oled_write_ln("Layer: Functions", false);
                break;
            case 3:
                oled_write_ln("Layer: Trackball", false);
                break;
            default:
                oled_write_ln("Layer: Undefined", false);
        }
    }

    return false;
}

